/**
 * Writes docs/whatsapp-templates.md: every WhatsApp template the app sends, ready to copy into
 * WhatsApp Manager (Meta Business Suite → WhatsApp Manager → Message templates → Create template).
 * Run: npm run wa:templates
 */
import fs from 'node:fs';
import path from 'node:path';
import { allWaTemplates, WA_PARAMS } from '../src/lib/waTemplates';

const t = allWaTemplates();
const names = [...new Set(t.map((x) => x.name))];
const lines: string[] = [
  '# WhatsApp message templates for Ahadi',
  '',
  'Generated by `npm run wa:templates` from `src/lib/waTemplates.ts`. Do not edit by hand.',
  '',
  'Create each template in **WhatsApp Manager → Message templates → Create template**. The **name**, **language** and **body** must match exactly (the app sends the variables in the order shown). Add the sample values when Meta asks for examples.',
  '',
  '## 1. Login code (category: Authentication)',
  '',
  '- Name: your choice, e.g. `ahadi_login_code`. Put it in `WHATSAPP_OTP_TEMPLATE`.',
  '- Languages: English (`en`) and Swahili (`sw`).',
  '- Code delivery: **Copy code** button. Meta writes the text for authentication templates; you only choose the options.',
  '',
  `## 2. Pledge and event messages (category: Utility) — ${names.length} templates × 2 languages`,
  '',
  '| Template name | Used for | Variables in order |',
  '| --- | --- | --- |',
];
const USE: Record<string, string> = {
  pledged: 'Pledge recorded (and personal link re-sent)',
  before: 'Reminder before the due date',
  due: 'Reminder on the due date',
  after: 'Reminder after the due date',
  thanks: 'Payment receipt',
  milestone: 'Organizer: 25/50/75/100% reached',
  invite: 'Committee member added',
};
for (const n of names) {
  const x = t.find((y) => y.name === n)!;
  const tone = x.name.endsWith('_warm') ? ' (weddings, birthdays, community)' : x.name.endsWith('_calm') ? ' (hospital, funeral)' : '';
  lines.push(`| \`${n}\` | ${USE[x.stage]}${tone} | ${WA_PARAMS[x.stage].map((k, i) => `{{${i + 1}}} ${k}`).join(', ')} |`);
}
lines.push('');
for (const n of names) {
  lines.push(`### \`${n}\``, '');
  for (const x of t.filter((y) => y.name === n)) {
    lines.push(`**${x.lang === 'en' ? 'English (en)' : 'Swahili (sw)'}**`, '', '```', x.body, '```', '');
    lines.push(`Sample values: ${x.example.map((v, i) => `{{${i + 1}}} = ${v}`).join(' · ')}`, '');
  }
}
lines.push(
  '## 3. Webhook (delivery reports)',
  '',
  'In your Meta app → WhatsApp → Configuration:',
  '',
  '- Callback URL: `https://<your-domain>/api/webhooks/whatsapp`',
  '- Verify token: any long random text; put the same value in `WHATSAPP_VERIFY_TOKEN`.',
  '- Subscribe to the **messages** field.',
  '- Put the app secret (App settings → Basic) in `WHATSAPP_APP_SECRET`.',
  '',
);
const out = path.join(process.cwd(), 'docs', 'whatsapp-templates.md');
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, lines.join('\n'));
console.log(`Wrote ${out} (${names.length} templates)`);
